ALTER TABLE public.unidades_consumidoras ADD COLUMN distribuidora text NOT NULL DEFAULT 'Equatorial Goiás', ADD COLUMN situacao text NOT NULL DEFAULT 'ativa' CHECK(situacao IN ('ativa','aguardando_rateio','inativa'));
UPDATE public.unidades_consumidoras SET situacao='inativa' WHERE ativa=false;
COMMENT ON COLUMN public.unidades_consumidoras.ativa IS 'DEPRECATED: replaced by situacao'; COMMENT ON COLUMN public.unidades_consumidoras.percentual_rateio IS 'DEPRECATED: replaced by rateios and rateio_configuracoes';
ALTER TABLE public.usinas ADD COLUMN potencia_modulo_w integer;
CREATE UNIQUE INDEX usinas_unidade_geradora_key ON public.usinas(unidade_geradora_id);
CREATE TABLE public.rateio_configuracoes(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid DEFAULT auth.uid(),vigencia_inicio date NOT NULL UNIQUE,vigencia_fim date,observacoes text,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),CHECK(vigencia_fim IS NULL OR vigencia_fim>=vigencia_inicio));
GRANT SELECT,INSERT,UPDATE,DELETE ON public.rateio_configuracoes TO authenticated; GRANT ALL ON public.rateio_configuracoes TO service_role; ALTER TABLE public.rateio_configuracoes ENABLE ROW LEVEL SECURITY;
CREATE POLICY autorizados_leem ON public.rateio_configuracoes FOR SELECT TO authenticated USING(public.is_authorized(auth.uid())); CREATE POLICY editores_inserem ON public.rateio_configuracoes FOR INSERT TO authenticated WITH CHECK(public.can_write(auth.uid())); CREATE POLICY editores_atualizam ON public.rateio_configuracoes FOR UPDATE TO authenticated USING(public.can_write(auth.uid())) WITH CHECK(public.can_write(auth.uid())); CREATE POLICY editores_excluem ON public.rateio_configuracoes FOR DELETE TO authenticated USING(public.can_write(auth.uid())); CREATE TRIGGER set_updated_at BEFORE UPDATE ON public.rateio_configuracoes FOR EACH ROW EXECUTE FUNCTION public.set_updated_at();
ALTER TABLE public.rateios ADD COLUMN configuracao_id uuid REFERENCES public.rateio_configuracoes(id) ON DELETE CASCADE,ADD CONSTRAINT rateios_configuracao_unidade_key UNIQUE(configuracao_id,unidade_id);
ALTER TABLE public.creditos ADD COLUMN fatura_id uuid REFERENCES public.faturas(id) ON DELETE CASCADE;
CREATE FUNCTION public.aplicar_rateio(_vigencia_inicio date,_percentuais jsonb,_observacoes text DEFAULT NULL) RETURNS uuid LANGUAGE plpgsql SECURITY INVOKER SET search_path=public AS $$ DECLARE _cfg uuid; _soma numeric; _ultima date; _vig date:=date_trunc('month',_vigencia_inicio)::date; BEGIN IF NOT public.can_write(auth.uid()) THEN RAISE EXCEPTION 'Você não tem permissão para alterar o rateio.' USING ERRCODE='42501'; END IF; CREATE TEMP TABLE _itens ON COMMIT DROP AS SELECT x.unidade_id,round(x.percentual,2) AS percentual FROM jsonb_to_recordset(_percentuais) AS x(unidade_id uuid,percentual numeric); IF EXISTS(SELECT 1 FROM _itens WHERE unidade_id IS NULL OR percentual IS NULL OR percentual<0 OR percentual>100) THEN RAISE EXCEPTION 'Percentual inválido' USING ERRCODE='22023'; END IF; IF(SELECT count(*)<>count(DISTINCT unidade_id) FROM _itens) THEN RAISE EXCEPTION 'Unidade duplicada' USING ERRCODE='22023'; END IF; IF EXISTS(SELECT 1 FROM _itens i LEFT JOIN unidades_consumidoras u ON u.id=i.unidade_id WHERE u.id IS NULL) THEN RAISE EXCEPTION 'Unidade inexistente' USING ERRCODE='22023'; END IF; IF EXISTS(SELECT 1 FROM unidades_consumidoras u WHERE u.situacao<>'inativa' AND NOT EXISTS(SELECT 1 FROM _itens i WHERE i.unidade_id=u.id)) THEN RAISE EXCEPTION 'Todas as unidades não inativas devem constar no rateio.' USING ERRCODE='22023'; END IF; IF EXISTS(SELECT 1 FROM _itens i JOIN unidades_consumidoras u ON u.id=i.unidade_id WHERE u.situacao='inativa' AND i.percentual>0) THEN RAISE EXCEPTION 'Unidade inativa não pode receber rateio' USING ERRCODE='22023'; END IF; SELECT coalesce(sum(percentual),0) INTO _soma FROM _itens; IF _soma<>100 THEN RAISE EXCEPTION 'A soma dos percentuais deve ser 100%%.' USING ERRCODE='22023'; END IF; SELECT max(vigencia_inicio) INTO _ultima FROM rateio_configuracoes; IF _ultima IS NOT NULL AND _vig<_ultima THEN RAISE EXCEPTION 'Vigência anterior à atual' USING ERRCODE='22023'; END IF; IF _ultima=_vig THEN DELETE FROM rateio_configuracoes WHERE vigencia_inicio=_vig; ELSE UPDATE rateio_configuracoes SET vigencia_fim=_vig-1 WHERE vigencia_fim IS NULL; UPDATE rateios SET vigencia_fim=_vig-1 WHERE vigencia_fim IS NULL; END IF; INSERT INTO rateio_configuracoes(vigencia_inicio,observacoes) VALUES(_vig,nullif(trim(_observacoes),'')) RETURNING id INTO _cfg; INSERT INTO rateios(configuracao_id,unidade_id,percentual,vigencia_inicio,observacoes) SELECT _cfg,unidade_id,percentual,_vig,nullif(trim(_observacoes),'') FROM _itens; UPDATE unidades_consumidoras u SET situacao='ativa' FROM _itens i WHERE i.unidade_id=u.id AND i.percentual>0 AND u.situacao='aguardando_rateio'; RETURN _cfg; END $$;
GRANT EXECUTE ON FUNCTION public.aplicar_rateio(date,jsonb,text) TO authenticated;